import { z } from 'zod';

// Same 15-character GSTIN shape check as the frontend's createSupplierSchema
// (see frontend/src/modules/masters/supplier/createSupplierSchema.js) —
// duplicated here rather than trusted from the client, same "never trust
// client validation alone" reasoning applied to every write endpoint in
// this app.
const GSTIN_PATTERN = /^\d{2}[A-Z]{5}\d{4}[A-Z][A-Z\d]Z[A-Z\d]$/;

// `code` is auto-generated by the CRUD factory (SUPP-0001, SUPP-0002, ...)
// unless the client supplies one explicitly — same convention as every
// other master (see crudFactory.js's nextCode()).
const supplierBaseSchema = z.object({
  code: z.string().trim().min(1).optional(),
  name: z.string().trim().min(1, 'Supplier name is required').max(150, 'Name cannot exceed 150 characters'),
  group: z.string().trim().optional().nullable(),
  phone: z.string().trim().optional().nullable(),
  email: z.string().trim().email('Enter a valid email').optional().or(z.literal('')).nullable(),
  gstNo: z.string().trim().optional().nullable(),
  country: z.string().trim().max(100, 'Country cannot exceed 100 characters').optional().nullable(),
  city: z.string().trim().optional().nullable(),
  state: z.string().trim().optional().nullable(),
  address: z.string().trim().max(500, 'Address cannot exceed 500 characters').optional().nullable(),
  remarks: z.string().trim().max(500, 'Remarks cannot exceed 500 characters').optional().nullable(),
  paymentTerms: z.string().trim().max(50, 'Payment terms cannot exceed 50 characters').optional().nullable(),
  status: z.enum(['ACTIVE', 'INACTIVE']).default('ACTIVE'),
});

// Phone/GST No. get a real format check here, not just "non-empty string" —
// same rules the frontend's createSupplierSchema enforces, duplicated
// rather than trusted from the client alone.
function withFormatChecks(schema) {
  return schema.superRefine((data, ctx) => {
    if (data.phone) {
      const digits = data.phone.replace(/\D/g, '');
      if (digits.length !== 10) {
        ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['phone'], message: 'Enter a valid 10-digit phone number' });
      }
    }
    if (data.gstNo && !GSTIN_PATTERN.test(data.gstNo.toUpperCase())) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['gstNo'], message: 'Enter a valid 15-character GSTIN' });
    }
  });
}

export const createSupplierSchema = withFormatChecks(supplierBaseSchema);
export const updateSupplierSchema = withFormatChecks(supplierBaseSchema.partial());
